import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const disposables = [];

  // Design tokens from NOVA_ATELIER_WORLD
  const colors = {
    ink: 0x16161d,
    surface: 0x0b0b10,
    accent: 0xff2a38,
    paper: 0xe8ecf2
  };

  // Filmstrip dimensions
  const CARD_W = 1.6;
  const CARD_H = 1.0;
  const PITCH = 1.85;
  const BEVEL = 0.025;
  const FOCUSED_IDX = 2;

  // Load image texture
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  texture.colorSpace = THREE.SRGBColorSpace;
  disposables.push(() => texture.dispose());

  // Card layout data
  const cardPositions = [-3.7, -1.85, 0, 1.85, 3.7];
  const cardNames = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE'
  ];

  const cards = [];
  const captions = [];

  // Build 5 cards with beveled frames
  for (let i = 0; i < 5; i++) {
    const cardGroup = new THREE.Group();
    cardGroup.position.x = cardPositions[i];
    cardGroup.userData.index = i;

    // Main card mesh with PBR material
    const cardGeo = new THREE.PlaneGeometry(CARD_W, CARD_H);
    const cardMat = new MeshStandardNodeMaterial({
      map: texture,
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true
    });
    const cardMesh = new THREE.Mesh(cardGeo, cardMat);
    cardMesh.position.z = 0.001;
    cardGroup.add(cardMesh);

    disposables.push(() => cardGeo.dispose());
    disposables.push(() => cardMat.dispose());

    // Bevel frame (machined ink border)
    const frameGeo = new THREE.PlaneGeometry(CARD_W + 2 * BEVEL, CARD_H + 2 * BEVEL);
    const frameMat = new THREE.MeshStandardMaterial({
      color: colors.ink,
      emissive: colors.ink,
      emissiveIntensity: 0.1
    });
    const frameMesh = new THREE.Mesh(frameGeo, frameMat);
    frameMesh.position.z = -0.001;
    cardGroup.add(frameMesh);

    disposables.push(() => frameGeo.dispose());
    disposables.push(() => frameMat.dispose());

    // Counter-rotate focused card to face camera dead-on
    if (i === FOCUSED_IDX) {
      cardGroup.rotation.y = (18 * Math.PI) / 180;
    }

    cards.push(cardGroup);
    group.add(cardGroup);

    // Create caption text for each card
    const caption = ctx.fontAtlas.create({
      text: cardNames[i],
      fontSize: 0.09,
      color: colors.paper
    });
    caption.position.set(cardPositions[i], -0.6, 0.01);
    caption.visible = (i === FOCUSED_IDX);
    captions.push(caption);
    group.add(caption);
  }

  // Red signal underline bar (focused card only)
  const barGeo = new THREE.PlaneGeometry(CARD_W, 0.035);
  const barMat = new THREE.MeshStandardMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.3
  });
  const bar = new THREE.Mesh(barGeo, barMat);
  bar.position.set(0, -(CARD_H / 2 + 0.025), 0.002);
  group.add(bar);

  disposables.push(() => barGeo.dispose());
  disposables.push(() => barMat.dispose());

  // Headline text (pinned position)
  const headline = ctx.fontAtlas.create({
    text: 'The collection',
    fontSize: 0.34,
    color: colors.paper
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  // Body text (pinned position)
  const bodyText = ctx.fontAtlas.create({
    text: 'Five calibres. One discipline.',
    fontSize: 0.13,
    color: colors.paper
  });
  bodyText.position.set(-2.6, -1.5, 0);
  group.add(bodyText);

  // Rotate entire strip -18° on y for perspective recession
  group.rotation.y = (-18 * Math.PI) / 180;

  // State
  group.userData.focusedIndex = FOCUSED_IDX;
  group.userData.cards = cards;
  group.userData.captions = captions;
  group.userData.bar = bar;

  // Update card display based on focused index
  const updateCardDisplay = (focusIdx) => {
    cards.forEach((card, idx) => {
      const distance = Math.abs(idx - focusIdx);
      const isFocused = distance === 0;

      // Scale: focused 1.0, others 0.92
      card.scale.setScalar(isFocused ? 1.0 : 0.92);

      // Opacity: 1.0 at center, falling to 0.55 by distance
      const cardMesh = card.children[0];
      if (cardMesh && cardMesh.material) {
        const opacity = isFocused ? 1.0 : Math.max(0.55, 1.0 - (distance / 4) * 0.45);
        cardMesh.material.opacity = opacity;
      }

      // Counter-rotation: only focused card faces camera
      card.rotation.y = isFocused ? (18 * Math.PI) / 180 : 0;
    });

    // Show only focused card's caption
    captions.forEach((cap, idx) => {
      cap.visible = (idx === focusIdx);
    });

    // Move underline bar to focused card
    bar.position.x = cards[focusIdx].position.x;
  };

  // Event handlers for scroll interaction
  group.userData.handlers = {
    onScroll: (scrollOffset) => {
      const targetIdx = Math.round(scrollOffset / PITCH);
      const clampedIdx = Math.max(0, Math.min(4, targetIdx));

      if (clampedIdx !== group.userData.focusedIndex) {
        group.userData.focusedIndex = clampedIdx;
        updateCardDisplay(clampedIdx);
      }
    },
    onScrollEnd: () => {
      // Snap to focused card with weighted-settle animation
      const focusIdx = group.userData.focusedIndex;
      const targetX = -cards[focusIdx].position.x;

      gsap.to(group.position, {
        x: targetX,
        duration: 0.9,
        ease: 'power2.inOut',
        overwrite: 'auto'
      });
    }
  };

  // Apply parallax-scroll cinematic primitive
  ctx.primitives['parallax-scroll'](group, { intensity: 0.5 });

  // Cleanup: dispose all resources and kill animations
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    disposables.forEach(dispose => dispose());
  };

  return group;
}
